ier":"C","threshold":65,"amount":500,"operator":"greater_or_equal"},{"tier":"D","threshold":60,"amount":300,"operator":"greater_or_equal"}]},{"key":"def_red_zone_td_rate","label":"Defensive Red-Zone TD Rate Allowed","scope":"team","direction":"lower_is_better","statKey":"red_zone_td_rate_allowed","tiers":[{"tier":"S","threshold":35,"amount":1500,"operator":"less_than"},{"tier":"A","threshold":40,"amount":1100,"operator":"less_than"},{"tier":"B","threshold":45,"amount":800,"operator":"less_than"},{"tier":"C","threshold":50,"amount":500,"operator":"less_than"},{"tier":"D","threshold":55,"amount":300,"operator":"less_than"}]},{"key":"time_of_possession","label":"Time of Possession Bonus","scope":"team","direction":"higher_is_better","statKey":"avg_time_of_possession_seconds","games":["cfb_27"],"tiers":[{"tier":"S","threshold":1110,"amount":1500,"operator":"greater_or_equal"},{"tier":"A","threshold":1080,"amount":1100,"operator":"greater_or_equal"},{"tier":"B","threshold":1050,"amount":800,"operator":"greater_or_equal"},{"tier":"C","threshold":1020,"amount":500,"operator":"greater_or_equal"},{"tier":"D","threshold":990,"amount":300,"operator":"greater_or_equal"}]},{"key":"well_disciplined","label":"Well-Disciplined (Penalties per Game)","scope":"team","direction":"lower_is_better","statKey":"total_penalties","games":["cfb_27","madden_26","madden_27"],"dataModes":["import"],"tiers":[{"tier":"S","threshold":1.2,"amount":1500,"operator":"less_than"},{"tier":"A","threshold":2,"amount":1100,"operator":"less_than"},{"tier":"B","threshold":3,"amount":800,"operator":"less_than"},{"tier":"C","threshold":4,"amount":500,"operator":"less_than"},{"tier":"D","threshold":5,"amount":300,"operator":"less_than"}]},{"key":"red_zone_finish_rate","label":"Red Zone Finish Rate","scope":"team","direction":"higher_is_better","statKey":"red_zone_td_finish_rate","games":["cfb_27","madden_26","madden_27"],"dataModes":["import"],"tiers":[{"tier":"S","threshold":90,"amount":1500,"operator":"greater