tackles, 250+ yards after contact, and 10+ rush TDs."},{"key":"king_of_the_swing","label":"King of the Swing","scope":"player","direction":"higher_is_better","statKey":"king_of_the_swing_qualified","games":["madden_26","madden_27"],"dataModes":["import"],"eligiblePositions":["K"],"minimums":{"fg_50_attempts":2},"tiers":[{"tier":"S","threshold":1,"amount":1000,"operator":"greater_or_equal"}],"triggerNote":"Pays 1,000 coins per user-team kicker with at least two 50+ yard field-goal attempts, all made."}]'::jsonb, true),
    version = version + 1,
    updated_at = now()
where config_key = 'global';

-- Refresh only unissued review items. Approved/issued history remains immutable.
update public.rec_eos_payout_items as item
set amount = case
  when item.payout_category = 'ranking' then case (item.metadata->>'rank')::integer
    when 1 then 7500 when 2 then 5500 when 3 then 4000 when 4 then 3000
    when 5 then 2500 when 6 then 2000 when 7 then 1500 when 8 then 1000 else 0 end
  when item.payout_key like '%:madden_rb_workhorse:%' then 2500
  when item.payout_key like '%:king_of_the_swing:%' then 1000
  when item.payout_category = 'team' then case item.qualified_tier
    when 'S' then 1500 when 'A' then 1100 when 'B' then 800 when 'C' then 500 when 'D' then 300 else item.amount end
  else item.amount
end
from public.rec_eos_payout_batches as batch
join public.rec_league_configuration as config on config.league_id = batch.league_id
where item.batch_id = batch.id
  and item.status = 'pending'
  and config.roster_type <> 'rise_to_immortality';
